  attachmentRow=row();attachmentRow.setPadding(dp(12),0,dp(12),0);attachmentRow.setVisibility(View.GONE);attachmentPreview=new ImageView(this);attachmentPreview.setScaleType(ImageView.ScaleType.CENTER_CROP);attachmentPreview.setOnClickListener(v->{if(pendingImageFile!=null)PhotoPreview.show(this,new File(getCacheDir(),"assistant-images/"+pendingImageFile));});attachmentRow.addView(attachmentPreview,new LinearLayout.LayoutParams(dp(44),dp(44)));attachmentLabel=text("图片已附加，发送时一起上传",12);attachmentLabel.setPadding(dp(10),0,dp(8),0);attachmentRow.addView(attachmentLabel,new LinearLayout.LayoutParams(0,-2,1));attachmentRow.addView(icon("close","移除附图",this::clearImage),new LinearLayout.LayoutParams(dp(56),dp(44)));root.addView(attachmentRow);
