 private void send(){if(busy)return;String value=input.getText().toString().trim();if(value.isEmpty()&&pendingImage==null)return;String picture=pendingImage;input.setText("");bubble("你",value,pendingImageFile);clearImage();setBusy(true,"正在理解并调用工具…");worker.execute(()->{try{engine.send(value,picture,new ChatEngine.Listener(){public boolean active(){return !closed&&!Thread.currentThread().isInterrupted();}public void message(String text){runOnUiThread(()->{if(!closed)bubble("助手",text);});}public void tool(String name,JSONObject result){runOnUiThread(()->{if(closed)return;if(result.has("error")){bubble("工具未完成",result.optString("error"));return;}if(result.has("staged_course_count")){bubble("课表待核验","已生成 "+result.optInt("staged_course_count")+" 门课程草稿，点击返回人工核验，校正表格后再创建。");}else if(result.optBoolean("changed")){bubble(result.optBoolean("deleted")?"已删除，可撤销":"已修改，可撤销",result.optString("title")+"\n"+result.optString("start_at")+" · "+result.optString("location"));}else if(result.optBoolean("created")){created.add(result.optString("id"));String time=result.optString("start_at",result.optString("due_date"));if(time.length()>=10)resultDate=time.substring(0,10);String label=result.optString("confirmation_status").equals("pending")?"待人工核验":"已创建";bubble(label,result.optString("title")+(time.isEmpty()?"":"\n"+time.replace('T',' '))+(result.optString("location").isEmpty()?"":"\n"+result.optString("location")));}else if(result.has("items"))status.setText("已查询 "+result.optJSONArray("items").length()+" 条摘要，正在整理…");});}});}catch(Exception e){showError(e);}finally{runOnUiThread(()->{if(!closed){setBusy(false,"已执行操作以结果卡片为准");persist();}});}});}
 private void undo(){if(busy)return;setBusy(true,"正在撤销…");worker.execute(()->{try{JSONObject result=engine.call("assistant_undo_last",new JSONObject());runOnUiThread(()->{if(!closed)bubble("撤销结果",result.optString("message"));});}catch(Exception e){showError(e);}finally{runOnUiThread(()->{if(!closed){setBusy(false,"");persist();}});}});}
 private void voice(){if(busy)return;try{startActivityForResult(new Intent().setComponent(new ComponentName(this,"app.dayflow.voice.MainActivity")),4);}catch(Exception e){bubble("语音",e.getMessage()==null?"无法打开语音识别模块":e.getMessage());}}
 private void pickImage(){if(busy)return;try{startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("image/*"),3);}catch(ActivityNotFoundException e){bubble("图片","手机没有可用的文件选择器，无法选择图片。");}}
