 private void attachImage(Uri uri)throws Exception{BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;try(InputStream in=getContentResolver().openInputStream(uri)){if(in==null)throw new IOException("图片不可读");BitmapFactory.decodeStream(in,null,bounds);}int sample=1;int max=1280;while(bounds.outWidth/(sample*2)>=max||bounds.outHeight/(sample*2)>=max)sample*=2;BitmapFactory.Options options=new BitmapFactory.Options();options.inSampleSize=sample;Bitmap bitmap;try(InputStream in=getContentResolver().openInputStream(uri)){if(in==null)throw new IOException("图片不可读");bitmap=BitmapFactory.decodeStream(in,null,options);}if(bitmap==null)throw new IOException("无法解码图片");int width=bitmap.getWidth(),height=bitmap.getHeight();float scale=Math.min(1f,(float)max/Math.max(width,height));if(scale<1f){Bitmap scaled=Bitmap.createScaledBitmap(bitmap,Math.max(1,Math.round(width*scale)),Math.max(1,Math.round(height*scale)),true);if(scaled!=bitmap)bitmap.recycle();bitmap=scaled;}ByteArrayOutputStream bytes=new ByteArrayOutputStream();bitmap.compress(Bitmap.CompressFormat.JPEG,80,bytes);String dataUrl="data:image/jpeg;base64,"+Base64.encodeToString(bytes.toByteArray(),Base64.NO_WRAP);File imageDir=new File(getCacheDir(),"assistant-images");imageDir.mkdirs();String filename=UUID.randomUUID()+".jpg";try(OutputStream saved=new FileOutputStream(new File(imageDir,filename))){saved.write(bytes.toByteArray());}File[] cache=imageDir.listFiles();if(cache!=null&&cache.length>40){Arrays.sort(cache,java.util.Comparator.comparingLong(File::lastModified));for(int i=0;i<cache.length-40;i++)cache[i].delete();}Bitmap preview=bitmap;runOnUiThread(()->{if(closed)return;pendingImage=dataUrl;pendingImageFile=filename;attachmentPreview.setImageBitmap(preview);attachmentRow.setVisibility(View.VISIBLE);status.setText("图片已附加，发送时一起上传");setBusy(false,"");});}
 protected void onActivityResult(int code,int result,Intent data){super.onActivityResult(code,result,data);if(code==4&&result==RESULT_OK&&data!=null){input.setText(data.getStringExtra("voice_text"));input.setSelection(input.length());return;}if(code==3&&result==RESULT_OK&&data!=null&&data.getData()!=null){Uri uri=data.getData();setBusy(true,"正在处理图片…");worker.execute(()->{try{attachImage(uri);}catch(Exception e){showError(e);runOnUiThread(()->{if(!closed)setBusy(false,"");});}});return;}if(code==2&&result==RESULT_OK&&data!=null){ArrayList<String> values=data.getStringArrayListExtra(RecognizerIntent.EXTRA_RESULTS);if(values!=null&&!values.isEmpty()){input.setText(values.get(0));input.setSelection(input.length());}}}
 private void setBusy(boolean value,String label){busy=value;send.setEnabled(!value);voice.setEnabled(!value);image.setEnabled(!value);undo.setEnabled(!value);status.setText(label);}
 private void showError(Exception e){runOnUiThread(()->{if(!closed)bubble("未完成",(e.getMessage()==null?"请求失败":e.getMessage())+"\n已经成功创建的事项保留，请核对结果后再重试。");});}
 private void bubble(String who,String value){bubble(who,value,null);}
 private void bubble(String who,String value,String imageFile){try{transcript.put(new JSONObject().put("who",who).put("text",value).put("image",imageFile==null?"":imageFile));while(transcript.length()>80)transcript.remove(0);}catch(Exception ignored){}addBubble(who,value,imageFile);}
 private void addBubble(String who,String value){addBubble(who,value,null);}
 private void addBubble(String who,String value,String imageFile){boolean mine=who.equals("你");LinearLayout line=row();line.setGravity(mine?Gravity.RIGHT:Gravity.LEFT);line.setPadding(mine?dp(36):0,dp(6),mine?0:dp(36),dp(6));LinearLayout bubble=column();bubble.setPadding(dp(14),dp(10),dp(14),dp(12));android.graphics.drawable.GradientDrawable bg=new android.graphics.drawable.GradientDrawable();bg.setColor(color(mine?com.google.android.material.R.attr.colorSecondaryContainer:com.google.android.material.R.attr.colorSurfaceContainerLow));bg.setCornerRadius(dp(18));bubble.setBackground(bg);if(!mine&&!who.equals("助手")){TextView label=text(who,11);label.setAlpha(.65f);bubble.addView(label);}if(imageFile!=null&&imageFile.matches("[a-f0-9-]+\\.jpg")){File file=new File(getCacheDir(),"assistant-images/"+imageFile);if(file.isFile()){ImageView imageView=new ImageView(this);imageView.setScaleType(ImageView.ScaleType.CENTER_CROP);BitmapFactory.Options opt=new BitmapFactory.Options();opt.inSampleSize=4;imageView.setImageBitmap(BitmapFactory.decodeFile(file.getPath(),opt));imageView.setContentDescription("点击预览已发送图片");imageView.setOnClickListener(v->PhotoPreview.show(this,file));bubble.addView(imageView,new LinearLayout.LayoutParams(dp(160),dp(160)));}}
 if(!value.isEmpty()){TextView body=text("",16);body.setMaxWidth(Math.max(dp(160),getResources().getDisplayMetrics().widthPixels-dp(110)));body.setTextIsSelectable(true);body.setLineSpacing(0,1.06f);Markdown.render(body,value);bubble.addView(body,new LinearLayout.LayoutParams(-2,-2));}line.addView(bubble,new LinearLayout.LayoutParams(-2,-2));messages.addView(line,new LinearLayout.LayoutParams(-1,-2));while(messages.getChildCount()>80)messages.removeViewAt(0);scroll.post(()->scroll.fullScroll(View.FOCUS_DOWN));}
 private MaterialButton icon(String name,String description,Runnable action){int resource=getResources().getIdentifier("assistant_ic_"+name,"drawable",getPackageName());MaterialButton b=new MaterialButton(this,null,com.google.android.material.R.attr.materialButtonOutlinedStyle);b.setText("");b.setStrokeWidth(0);b.setIconResource(resource);b.setIconSize(dp(23));b.setIconPadding(0);b.setIconGravity(MaterialButton.ICON_GRAVITY_TEXT_START);b.setIconTint(android.content.res.ColorStateList.valueOf(color(androidx.appcompat.R.attr.colorPrimary)));b.setContentDescription(description);b.setTooltipText(description);b.setMinWidth(0);b.setMinimumWidth(0);b.setPadding(dp(10),0,dp(10),0);b.setInsetTop(0);b.setInsetBottom(0);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(android.graphics.Color.TRANSPARENT));b.setOnClickListener(v->action.run());return b;}
 private void persist(){try{android.util.AtomicFile file=new android.util.AtomicFile(new File(getCacheDir(),"assistant-chat.json"));FileOutputStream out=null;try{out=file.startWrite();out.write(new JSONObject().put("history",new JSONArray(engine.snapshot())).put("transcript",transcript).toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));file.finishWrite(out);}catch(Exception e){if(out!=null)file.failWrite(out);}}catch(Exception ignored){}}
 private void load(){try(InputStream in=new FileInputStream(new File(getCacheDir(),"assistant-chat.json"))){JSONObject saved=new JSONObject(ChatEngine.read(in));engine.restore(saved.getJSONArray("history").toString());JSONArray log=saved.getJSONArray("transcript");for(int i=Math.max(0,log.length()-80);i<log.length();i++){JSONObject r=log.getJSONObject(i);transcript.put(r);addBubble(r.optString("who"),r.optString("text"),r.optString("image"));}}catch(Exception ignored){}}
 protected void onDestroy(){closed=true;worker.shutdownNow();super.onDestroy();}
 private int dp(int value){return Math.round(value*getResources().getDisplayMetrics().density);}private int color(int attr){return MaterialColors.getColor(this,attr,0xff386a5c);}private LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);return l;}private LinearLayout row(){LinearLayout l=column();l.setOrientation(0);l.setGravity(Gravity.CENTER_VERTICAL);return l;}
 private TextView text(String value,int size){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(color(com.google.android.material.R.attr.colorOnSurface));return t;}private MaterialButton button(String label,Runnable action){MaterialButton b=new MaterialButton(this,null,com.google.android.material.R.attr.materialButtonOutlinedStyle);b.setText(label);b.setSingleLine(true);b.setMinWidth(0);b.setMinimumWidth(0);b.setPadding(dp(4),0,dp(4),0);b.setOnClickListener(v->action.run());return b;}
